package com.ptracker.app;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.view.*;import android.widget.*;import android.print.*;import android.util.Base64;import java.io.*;
public class MainActivity extends Activity {
 private WebView web;private ValueCallback<Uri[]> upload;private byte[] pending;private String pendingName;private boolean saving=false;
 private static final String HOST="app.ptracker.local";private static final String HOME="https://"+HOST+"/index.html";
 @Override public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);web.setBackgroundColor(0xffFFF6F9);web.setOverScrollMode(View.OVER_SCROLL_NEVER);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportZoom(false);s.setTextZoom(100);web.addJavascriptInterface(new Bridge(),"Android");
 web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){Uri u=r.getUrl();String h=u.getHost();if("https".equals(u.getScheme())&&HOST.equals(h)){String p=u.getPath();String mime="text/plain";if(p.endsWith(".html"))mime="text/html";else if(p.endsWith(".js"))mime="application/javascript";else if(p.endsWith(".css"))mime="text/css";else if(p.endsWith(".svg"))mime="image/svg+xml";else if(p.endsWith(".json"))mime="application/json";try{return new WebResourceResponse(mime,"UTF-8",getAssets().open(p.substring(1)));}catch(IOException e){}}if("generativelanguage.googleapis.com".equals(h))return null;return new WebResourceResponse("text/plain","UTF-8",403,"Blocked",java.util.Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !HOME.equals(r.getUrl().toString());}});
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(upload!=null)upload.onReceiveValue(null);upload=cb;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");try{startActivityForResult(i,11);}catch(Exception e){upload.onReceiveValue(null);upload=null;notice("No file picker available.");}return true;}@Override public boolean onJsAlert(WebView v,String u,String m,JsResult r){new AlertDialog.Builder(MainActivity.this).setMessage(m).setPositiveButton("OK",(d,w)->r.confirm()).setOnCancelListener(d->r.cancel()).show();return true;}@Override public boolean onJsConfirm(WebView v,String u,String m,JsResult r){new AlertDialog.Builder(MainActivity.this).setTitle("P Tracker").setMessage(m).setPositiveButton("Confirm",(d,w)->r.confirm()).setNegativeButton("Cancel",(d,w)->r.cancel()).setOnCancelListener(d->r.cancel()).show();return true;}});web.loadUrl(HOME);}
 private void notice(String m){Toast.makeText(this,m,Toast.LENGTH_LONG).show();}
 public class Bridge {
  @JavascriptInterface public void theme(boolean dark){runOnUiThread(()->{getWindow().setStatusBarColor(dark?0xff2A1520:0xffFFF6F9);getWindow().setNavigationBarColor(dark?0xff2A1520:0xffFFFFFF);getWindow().getDecorView().setSystemUiVisibility(dark?0:(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR));});}
  @JavascriptInterface public void save(String b64,String name,String mime){if(b64.length()>35000000){runOnUiThread(()->notice("File too large."));return;}runOnUiThread(()->{if(saving){notice("Finish the current file save first.");return;}try{pending=Base64.decode(b64,Base64.DEFAULT);pendingName=name.replaceAll("[^a-zA-Z0-9._-]","_");saving=true;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime.split(";")[0]);i.putExtra(Intent.EXTRA_TITLE,pendingName);startActivityForResult(i,12);}catch(Exception e){pending=null;saving=false;notice("Unable to open file save picker.");}});}
  @JavascriptInterface public void print(){runOnUiThread(()->{try{PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);pm.print("P Tracker report",web.createPrintDocumentAdapter("P Tracker report"),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).build());}catch(Exception e){notice("Android print service is unavailable.");}});}
  @JavascriptInterface public void exit(){runOnUiThread(()->new AlertDialog.Builder(MainActivity.this).setTitle("Close P Tracker?").setMessage("Data is phone pe saved rahega.").setNegativeButton("Stay",null).setPositiveButton("Close",(d,w)->finish()).show());}
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==11&&upload!=null){upload.onReceiveValue(result==RESULT_OK&&data!=null&&data.getData()!=null?new Uri[]{data.getData()}:null);upload=null;}if(request==12){if(result==RESULT_OK&&data!=null&&data.getData()!=null&&pending!=null){byte[] bytes=pending;Uri dest=data.getData();new Thread(()->{try(OutputStream out=getContentResolver().openOutputStream(dest)){if(out==null)throw new IOException();out.write(bytes);runOnUiThread(()->notice("Backup saved."));}catch(Exception e){runOnUiThread(()->notice("Save failed. Please try again."));}}).start();}else notice("Save cancelled.");pending=null;saving=false;}}
 @Override public void onBackPressed(){web.evaluateJavascript("window.androidBack && window.androidBack()",null);}
 @Override protected void onDestroy(){if(upload!=null)upload.onReceiveValue(null);web.removeJavascriptInterface("Android");web.destroy();super.onDestroy();}
}
